// Cloudflare Workers entry: the OpenNext worker for every request, plus the
// daily ritual scan that vercel.json's cron used to run, and a 15-minute sweep for overdue
// Safe & sound check-ins. The Cron Triggers are declared in wrangler.jsonc; the routes check
// Authorization: Bearer CRON_SECRET.
// `.open-next/worker.js` is generated by `npm run cf:build`.
import handler from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,
  async scheduled(event, env, ctx) {
    const origin = (env.APP_ORIGIN || "https://nearer.invalid").replace(/\/$/, "");
    // The every-15-minutes trigger sweeps overdue check-ins; the daily one runs the ritual scan.
    const job = event.cron === "*/15 * * * *" ? "push/sweep" : "ritual-scan";
    const req = new Request(`${origin}/api/${job}`, { headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` } });
    const res = await handler.fetch(req, env, ctx);
    console.log(`[cron] ${job} ${res.status}`);
  },
};
